CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(3227,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','matthew',27,55,$n$The women-witnessing-the-Cross.$n$,$n$Matthew 27:55 — *And many women were there beholding afar off, which followed Yahusha (Jesus) from Galilee, ministering unto him:* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) The two who came at dawn are not strangers. Matthew has already told us there were many women at the cross, watching from far off, and they had come *from Galilee*. The women at the tomb are the same women who stayed when the twelve were gone.$n$,25,$n$The women-witnessing-the-Cross.$n$,$n$Matthew 27:55 — *many women were there beholding afar off.* The many women watching from far off are the ones who then come to the sepulchre at first light.$n$),
(3228,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','matthew',27,61,$n$The women-witnessing-the-burial.$n$,$n$Matthew 27:61 — *And there was Mary Magdalene, and the other Mary, sitting over against the sepulchre.* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) Before they came to the tomb they sat at it. The two Marys were *sitting over against the sepulchre* and watched where he was laid. So when they come at first light, they come knowing the place, having seen the burial with their own eyes.$n$,25,$n$The women-witnessing-the-burial.$n$,$n$Matthew 27:61 — *Mary Magdalene, and the other Mary, sitting over against the sepulchre.* The same two who come at dawn were there at the burial, watching the grave and knowing the place.$n$),
(3216,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','mark',16,1,$n$The Markan-parallel.$n$,$n$Mark 16:1 — *And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) The same morning from the women's side. The sabbath was past and they had *bought sweet spices* to anoint a body they took to be still in the grave. Matthew gives the hour, Mark gives the errand, and both have the same faithful women walking to the same tomb.$n$,25,$n$The Markan-parallel.$n$,$n$Mark 16:1 — *had bought sweet spices, that they might come and anoint him.* The women arrive with bought spices and a purpose, which gives Matthew's two Marys their errand at the sepulchre.$n$),
(3217,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','luke',24,1,$n$The Lukan-parallel.$n$,$n$Luke 24:1 — *Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them.* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) Luke gives the same dawn. They came on the first day, *very early in the morning*, carrying spices they had made ready beforehand. Matthew's women and Luke's are the same faithful witnesses, walking to a tomb they expected to find shut with him inside it.$n$,25,$n$The Lukan-parallel + the substantial-substance-of-the-substantial-disbelief-of-the-male-disciples-substance.$n$,$n$Luke 24:1 — *they came unto the sepulchre, bringing the spices which they had prepared.* Luke shows the women bringing prepared spices with others beside them, the company Matthew's two Marys belong to.$n$),
(3229,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','john',20,11,$n$Miryam Magdalene-substance.$n$,$n$John 20:11 — *But Mary stood without at the sepulchre weeping: and as she wept, she stooped down, and looked into the sepulchre,* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) John stays with Mary. She *stood without at the sepulchre weeping* once the men had gone home, and she stooped down to look in. The one who came at dawn is the one who will not leave, and she is the one Yahusha (Jesus) speaks to first.$n$,25,$n$Miryam Magdalene-substance.$n$,$n$John 20:11 — *Mary stood without at the sepulchre weeping.* Mary stays at the grave weeping and looks in, the same woman who came with the others at dawn.$n$),
(3230,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','john',19,25,$n$The substantial-women-at-the-Cross.$n$,$n$John 19:25 — *Now there stood by the cross of Yahusha (Jesus) his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene.* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) John names the women at the cross, *his mother* among them, then Mary the wife of Cleophas, and Mary Magdalene. Mary Magdalene is there again. The one who stands at the cross is the one who comes at dawn to the grave.$n$,25,$n$The substantial-women-at-the-Cross.$n$,$n$John 19:25 — *Mary the wife of Cleophas, and Mary Magdalene.* Mary Magdalene is named among the women standing at the cross, the same woman who comes to the sepulchre.$n$),
(3231,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','proverbs',31,10,$n$The substantial-Tanakh-virtuous-woman-substance.$n$,$n$Proverbs 31:10 — *Who can find a virtuous woman? for her price is far above rubies.* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) The proverb asks *who can find a virtuous woman*, and Matthew answers with names. Mary Magdalene and the other Mary came to the grave while it was still dawning. Their *price is far above rubies*, and they are found where the faithful are found, at the place everyone else left.$n$,25,$n$The substantial-Tanakh-virtuous-woman-substance.$n$,$n$Proverbs 31:10 — *Who can find a virtuous woman? for her price is far above rubies.* The proverb's question is answered by named women who were found at the grave when others had gone.$n$),
(3232,'canon','matthew',28,1,$n$In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.$n$,'canon','luke',8,1,$n$The substantial-women-supporting-the-ministry-substance.$n$,$n$Luke 8:1 — *And it came to pass afterward, that he went throughout every city and village, preaching and shewing the glad tidings of the kingdom of Elohim (God): and the twelve were with him,* *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1) Luke begins the story of how they came to be there. He went *throughout every city and village*, and the twelve were with him, and the next lines name the women who were with them too, Mary called Magdalene and others. They followed from the first, long before the cross.$n$,25,$n$The substantial-women-supporting-the-ministry-substance.$n$,$n$Luke 8:1 — *went throughout every city and village, preaching and shewing the glad tidings.* The women who stand at the tomb had travelled with him through every city and village from the start.$n$),
(7123,'canon','luke',24,1,$n$Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them.$n$,'canon','matthew',28,1,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | Luke carries the women-at-the-tomb-as-first-witnesses substance — Miriam Magdalit (Mary Magdalene), Yochanah (Joanna), Miriam mother of Ya'aqov, and others. The framework-major women-first-witnesses pattern walked into Luke.$n$,$n$Matthew 28:1 — *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* *Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them.* (Luke 24:1) Luke says *they came unto the sepulchre* and leaves most of them unnamed. Matthew names the two at the front, *Mary Magdalene and the other Mary*. Put together, the company Luke describes had these two leading it, and they are the same two who sat at the grave.$n$,25,$n$Luke carries the women-at-the-tomb-as-first-witnesses substance — Miriam Magdalit (Mary Magdalene), Yochanah (Joanna), Miriam mother of Ya'aqov, and others. The framework-major women-first-witnesses pattern walked into Luke.$n$,$n$Matthew 28:1 — *came Mary Magdalene and the other Mary to see the sepulchre.* Matthew puts names to the company Luke leaves unnamed: Mary Magdalene and the other Mary.$n$),
(5358,'canon','mark',15,40,$n$There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;$n$,'canon','matthew',27,55,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | *Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome.* The women at the cross — named here as witnesses of the crucifixion the same way they will be named as the first witnesses of the resurrection.$n$,$n$Matthew 27:55 — *And many women were there beholding afar off, which followed Yahusha (Jesus) from Galilee, ministering unto him:* *There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;* (Mark 15:40) Mark names the women watching from far off. Matthew says who they were to him: they had *followed* him *from Galilee*, and they were *ministering unto him* the whole way. These are not onlookers from the crowd. They are the ones who kept him.$n$,25,$n$*Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome.* The women at the cross — named here as witnesses of the crucifixion the same way they will be named as the first witnesses of the resurrection.$n$,$n$Matthew 27:55 — *which followed Yahusha (Jesus) from Galilee, ministering unto him.* The women Mark names at the cross had followed Yahusha (Jesus) from Galilee and served him.$n$),
(5359,'canon','mark',15,40,$n$There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;$n$,'canon','luke',23,49,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | The Lukan parallel of the women at the cross.$n$,$n$Luke 23:49 — *And all his acquaintance, and the women that followed him from Galilee, stood afar off, beholding these things.* *There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;* (Mark 15:40) Luke puts it plainly: *all his acquaintance*, and *the women that followed him from Galilee*, stood far off and watched. Mark names three of them, and Luke tells us they had followed from Galilee too. Same women, same place, seen from another side.$n$,25,$n$The Lukan parallel of the women at the cross.$n$,$n$Luke 23:49 — *the women that followed him from Galilee, stood afar off, beholding these things.* Luke says the women who followed from Galilee stood at a distance and watched, as Mark has them.$n$),
(5360,'canon','mark',15,40,$n$There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;$n$,'canon','john',19,25,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | The Johannine parallel of the women at the cross.$n$,$n$John 19:25 — *Now there stood by the cross of Yahusha (Jesus) his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene.* *There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;* (Mark 15:40) John brings the women right up to the cross. *Mary Magdalene* is there again, with the mother of Yahusha (Jesus) and her sister. Mark has them at a distance. John says they *stood by the cross*. They stayed close to the end.$n$,25,$n$The Johannine parallel of the women at the cross.$n$,$n$John 19:25 — *Mary the wife of Cleophas, and Mary Magdalene.* John lists Mary Magdalene among the women standing at the cross, close to where Mark has them watching.$n$),
(5363,'canon','mark',16,1,$n$And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.$n$,'canon','matthew',28,1,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | *Mary Magdalene, and Mary the mother of James, and Salome.* The Markan women coming to anoint the body, finding the stone rolled away. The Matthean parallel.$n$,$n$Matthew 28:1 — *In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* *And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.* (Mark 16:1) Mark has the women coming with spices to anoint him. Matthew gives the hour, *as it began to dawn*, and says they came *to see the sepulchre*. Two accounts, one dawn, the same two Marys walking to the grave.$n$,25,$n$*Mary Magdalene, and Mary the mother of James, and Salome.* The Markan women coming to anoint the body, finding the stone rolled away. The Matthean parallel.$n$,$n$Matthew 28:1 — *as it began to dawn toward the first day of the week.* Matthew gives the dawn hour at which Mark's women come to the grave, with Mary Magdalene and the other Mary named.$n$),
(5364,'canon','mark',16,1,$n$And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.$n$,'canon','luke',24,1,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | The Lukan parallel of the women at the tomb.$n$,$n$Luke 24:1 — *Now upon the first day of the week, very early in the morning, they came unto the sepulchre, bringing the spices which they had prepared, and certain others with them.* *And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.* (Mark 16:1) Luke shows the spices in their hands. They came *very early in the morning*, *bringing the spices*, and *certain others* with them. The errand Mark gives is carried out, and more women walk with the three he names.$n$,25,$n$The Lukan parallel of the women at the tomb.$n$,$n$Luke 24:1 — *bringing the spices which they had prepared, and certain others with them.* Luke shows the errand Mark names being carried out, with other women beside the ones named.$n$),
(5365,'canon','mark',16,1,$n$And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.$n$,'canon','john',20,1,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | The Johannine parallel of Mary Magdalene at the tomb.$n$,$n$John 20:1 — *The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre.* *And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.* (Mark 16:1) John follows Mary Magdalene alone, *early, when it was yet dark*. Mark has her with the others and the spices. John has her seeing *the stone taken away* and running with the news. Whoever else is with her, she is the one who is there first.$n$,25,$n$The Johannine parallel of Mary Magdalene at the tomb.$n$,$n$John 20:1 — *Mary Magdalene early, when it was yet dark, unto the sepulchre.* John shows Mary Magdalene at the sepulchre in the dark, the first to see the stone moved.$n$),
(5370,'canon','mark',16,8,$n$And they went out quickly, and fled from the sepulchre; for they trembled and were amazed: neither said they any thing to any man; for they were afraid.$n$,'canon','matthew',28,8,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | *And they went out quickly, and fled from the sepulchre; for they trembled and were amazed.* The fear is the faithful-witness fear of the resurrection-substance breaking into the world.$n$,$n$Matthew 28:8 — *And they departed quickly from the sepulchre with fear and great joy; and did run to bring his disciples word.* *And they went out quickly, and fled from the sepulchre; for they trembled and were amazed: neither said they any thing to any man; for they were afraid.* (Mark 16:8) Mark tells how they trembled. Matthew shows the same fear and says it came with *great joy*, so they *did run to bring his disciples word*. Fear is in both accounts, and in Matthew it does not keep them from the errand they were sent on.$n$,25,$n$*And they went out quickly, and fled from the sepulchre; for they trembled and were amazed.* The fear is the faithful-witness fear of the resurrection-substance breaking into the world.$n$,$n$Matthew 28:8 — *departed quickly from the sepulchre with fear and great joy.* Matthew keeps the women's fear but joins it to joy and a run to carry the word to the disciples.$n$),
(5372,'canon','mark',16,9,$n$Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.$n$,'canon','matthew',28,9,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | The Matthean parallel of the women meeting the risen King.$n$,$n$Matthew 28:9 — *And as they went to tell his disciples, behold, Yahusha (Jesus) met them, saying, All hail. And they came and held him by the feet, and worshipped him.* *Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.* (Mark 16:9) Mark says he appeared first to Mary Magdalene. Matthew shows the meeting. As they went, Yahusha (Jesus) *met them*, and they *held him by the feet, and worshipped him*. The first to be seen by him are the women, and they take hold of him and worship.$n$,25,$n$The Matthean parallel of the women meeting the risen King.$n$,$n$Matthew 28:9 — *they came and held him by the feet, and worshipped him.* Matthew shows the women meeting the risen Yahusha (Jesus), taking hold of his feet and worshipping.$n$),
(5371,'canon','mark',16,9,$n$Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.$n$,'canon','john',20,11,$n$thread:women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance | *Mary Magdalene as the first to whom the risen King appeared.* The framework's first-shall-be-last reversal walked out at the empty tomb (Yochanan/John 20:11-18).$n$,$n$John 20:11 — *But Mary stood without at the sepulchre weeping: and as she wept, she stooped down, and looked into the sepulchre,* *Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.* (Mark 16:9) Mark says he appeared first to Mary Magdalene. John shows how it went. She *stood without at the sepulchre weeping* and stooped to look in, and it is to her that Yahusha (Jesus) then speaks and sends. The first to be seen is the woman who would not leave the grave.$n$,25,$n$*Mary Magdalene as the first to whom the risen King appeared.* The framework's first-shall-be-last reversal walked out at the empty tomb (Yochanan/John 20:11-18).$n$,$n$John 20:11 — *as she wept, she stooped down, and looked into the sepulchre.* John shows Mary weeping at the empty tomb and looking in, the woman Mark says he appeared to first.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (25, 'women-as-the-first-witnesses-of-the-resurrection-and-the-faithful-witness-substance', $n$The women who followed from Galilee — at the cross, at the burial, and first at the empty tomb (Luke 8; John 20; Deuteronomy 19)$n$, $n$The women who followed from Galilee — at the cross, at the burial, and first at the empty tomb (Luke 8; John 20; Deuteronomy 19)$n$, $n$It ain't new. The same women are at every station. They had followed him from Galilee and kept him out of their own means:

*And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,* (Luke 8:2)

*And Joanna the wife of Chuza Herod’s steward, and Susanna, and many others, which ministered unto him of their substance.* (Luke 8:3)

They stood at the cross when the twelve were gone:

*And many women were there beholding afar off, which followed Yahusha (Jesus) from Galilee, ministering unto him:* (Matthew 27:55)

*Among which was Mary Magdalene, and Mary the mother of James and Joses, and the mother of Zebedee’s children.* (Matthew 27:56)

*Now there stood by the cross of Yahusha (Jesus) his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene.* (John 19:25)

They sat at the burial:

*And there was Mary Magdalene, and the other Mary, sitting over against the sepulchre.* (Matthew 27:61)

And they came first to the tomb and were the first told, the first sent, and the first he met:

*In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1)

*And go quickly, and tell his disciples that he is risen from the dead; and, behold, he goeth before you into Galilee; there shall ye see him: lo, I have told you.* (Matthew 28:7)

*And as they went to tell his disciples, behold, Yahusha (Jesus) met them, saying, All hail. And they came and held him by the feet, and worshipped him.* (Matthew 28:9)

*Then said Yahusha (Jesus) unto them, Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me.* (Matthew 28:10)

Mark says it outright, and John tells what Mary was given to carry:

*Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.* (Mark 16:9)

*Yahusha (Jesus) saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my Elohim (God), and your Elohim (God).* (John 20:17)

*Mary Magdalene came and told the disciples that she had seen Yahusha (Lord), and that he had spoken these things unto her.* (John 20:18)

*Go tell my brethren*: the first witness of the rising is a woman carrying the word to the men. The Torah establishes a matter at the mouth of two or three witnesses, and there were two Marys at the tomb, the same two who had sat at the grave and stood at the cross:

*One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established.* (Deuteronomy 19:15)

Who can find such a woman, the proverb asks, and the gospels answer with names: Mary Magdalene, the other Mary, Joanna, Susanna, and many others, who saw the death, the burial and the empty grave with their own eyes and were believed by the brethren because they were sent.

*Who can find a virtuous woman? for her price is far above rubies.* (Proverbs 31:10)$n$, $n$It ain't new. The same women are at every station. They had followed him from Galilee and kept him out of their own means:

*And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,* (Luke 8:2)

*And Joanna the wife of Chuza Herod’s steward, and Susanna, and many others, which ministered unto him of their substance.* (Luke 8:3)

They stood at the cross when the twelve were gone:

*And many women were there beholding afar off, which followed Yahusha (Jesus) from Galilee, ministering unto him:* (Matthew 27:55)

*Among which was Mary Magdalene, and Mary the mother of James and Joses, and the mother of Zebedee’s children.* (Matthew 27:56)

*Now there stood by the cross of Yahusha (Jesus) his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene.* (John 19:25)

They sat at the burial:

*And there was Mary Magdalene, and the other Mary, sitting over against the sepulchre.* (Matthew 27:61)

And they came first to the tomb and were the first told, the first sent, and the first he met:

*In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.* (Matthew 28:1)

*And go quickly, and tell his disciples that he is risen from the dead; and, behold, he goeth before you into Galilee; there shall ye see him: lo, I have told you.* (Matthew 28:7)

*And as they went to tell his disciples, behold, Yahusha (Jesus) met them, saying, All hail. And they came and held him by the feet, and worshipped him.* (Matthew 28:9)

*Then said Yahusha (Jesus) unto them, Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me.* (Matthew 28:10)

Mark says it outright, and John tells what Mary was given to carry:

*Now when Yahusha (Jesus) was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.* (Mark 16:9)

*Yahusha (Jesus) saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my Elohim (God), and your Elohim (God).* (John 20:17)

*Mary Magdalene came and told the disciples that she had seen Yahusha (Lord), and that he had spoken these things unto her.* (John 20:18)

*Go tell my brethren*: the first witness of the rising is a woman carrying the word to the men. The Torah establishes a matter at the mouth of two or three witnesses, and there were two Marys at the tomb, the same two who had sat at the grave and stood at the cross:

*One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established.* (Deuteronomy 19:15)

Who can find such a woman, the proverb asks, and the gospels answer with names: Mary Magdalene, the other Mary, Joanna, Susanna, and many others, who saw the death, the burial and the empty grave with their own eyes and were believed by the brethren because they were sent.

*Who can find a virtuous woman? for her price is far above rubies.* (Proverbs 31:10)$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 25 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 25 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (women-as-the-first) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — women-as-the-first done.'
